async function checkSavedSearch(search: SavedSearch): Promise<void> {
  const newListings = await db.listings.findMany({
    where: {
      createdAt: { gt: search.lastCheckedAt },
      ...matchFilters(search.filters),
    },
  });

  for (const listing of newListings) {
    await sendAlertEmail(search.userId, listing);
  }

  await db.savedSearch.update({
    where: { id: search.id },
    data: { lastCheckedAt: new Date() },
  });
}
